"      const hasOptions = optionGroups.some(og => og.item_id === item.id);
      if (hasOptions) {
        setSelectedItemForModifiers(item);
      } else {
        setLastAddedItemId(item.id);
        const tierPrice = getItemDisplayPrice(item);
        const label = getItemPriceLabel();
        setCart(prev => {
          // Match by both id AND price so same item at different tiers coexist
          const existing = prev.find(c => c.id === item.id && parseFloat(c.price) === tierPrice && c.priceLabel === label);
          if (existing) return prev.map(c => (c.id === item.id && parseFloat(c.price) === tierPrice && c.priceLabel === label) ? { ...c, quantity: c.quantity + 1 } : c);
          return [...prev, { ...item, price: tierPrice, original_price: item.price, quantity: 1, priceLabel: label }];
        });
      }
